//! Executed pinned TypeScript/Swift outputs and the uniform schema's JavaScript-packed vector;
//! never generated by the Rust implementation. The descriptor-path mapping vectors
//! (`conformance/packing/descriptors.json`) and the relative level source's vectors
//! (`conformance/packing/levels.json`) come from the standard-library model in
//! `tools/mapping-vectors.py`.
mod json;
use json::Value;
use oscillux_core::{
    curves::*,
    dsp::{Descriptors, DspFrame, Levels},
    governor::*,
    mapping::*,
    packing::*,
};

fn opt<'a>(v: &'a Value, key: &str) -> Option<&'a Value> {
    match v {
        Value::Obj(fields) => fields
            .iter()
            .find(|(k, _)| k == key)
            .map(|(_, v)| v)
            .filter(|v| !matches!(v, Value::Null)),
        _ => None,
    }
}
fn number(v: &Value, key: &str, default: f64) -> f64 {
    opt(v, key).map_or(default, Value::num)
}
fn string<'a>(v: &'a Value, key: &str) -> &'a str {
    opt(v, key).map_or("", Value::str)
}
fn boolean(v: &Value, key: &str) -> bool {
    opt(v, key).is_some_and(Value::boolean)
}
fn numeric_kind(value: &str, names: &[&str]) -> u32 {
    names.iter().position(|s| *s == value).unwrap() as u32
}
fn near(got: f64, want: f64, tolerance: f64) {
    assert!(got.is_finite() && want.is_finite());
    assert!((got - want).abs() <= tolerance, "got {got}, want {want}");
}
fn curve(v: &Value) -> Curve {
    let kind = numeric_kind(
        string(v, "kind"),
        &["constant", "easing", "envelope", "lfo"],
    );
    let mut flags = 0;
    for (key, flag) in [
        ("value", VALUE),
        ("from", FROM),
        ("to", TO),
        ("min", MIN),
        ("max", MAX),
    ] {
        if opt(v, key).is_some() {
            flags |= flag;
        }
    }
    if boolean(v, "wrap") {
        flags |= WRAP;
    }
    Curve {
        kind,
        flags,
        unit: numeric_kind(string(v, "unit"), &["", "seconds", "beats"]),
        easing: match string(v, "easing") {
            "" | "linear" => 0,
            "easeIn" => 1,
            "easeOut" => 2,
            "easeInOut" => 3,
            _ => panic!("easing"),
        },
        shape: match string(v, "shape") {
            "" | "sine" => 0,
            "triangle" => 1,
            "square" => 2,
            _ => panic!("shape"),
        },
        value: number(v, "value", 0.0),
        from: number(v, "from", 0.0),
        to: number(v, "to", 0.0),
        duration: number(v, "duration", 0.0),
        attack: number(v, "attack", 0.0),
        release: number(v, "release", 0.0),
        release_at: number(v, "releaseAt", 0.0),
        period: number(v, "period", 0.0),
        phase: number(v, "phase", 0.0),
        min: number(v, "min", 0.0),
        max: number(v, "max", 0.0),
        smoothing_seconds: number(v, "smoothingSeconds", 0.0),
    }
}
#[test]
fn curves_match_pinned_evaluators_and_ts_rounding() {
    let doc = json::parse(include_str!("../../../conformance/curves/reference.json")).unwrap();
    let mut maximum = 0.0f64;
    for case in doc.get("cases").arr() {
        let input = case.get("input");
        let input = CurveInput {
            elapsed_seconds: number(input, "elapsedSeconds", 0.0),
            elapsed_beats: number(input, "elapsedBeats", 0.0),
            beat_phase: number(input, "beatPhase", 0.0),
            delta_seconds: number(input, "deltaSeconds", 0.0),
            previous_value: number(input, "previousValue", 0.0),
            has_previous: u32::from(boolean(input, "hasPrevious")),
        };
        let got = curve(case.get("curve")).evaluate(&input).unwrap();
        let want = case.get("want").num();
        near(got, want, doc.get("tolerance").num());
        maximum = maximum.max((got - want).abs());
        if case.get("source").str().starts_with("TS-boundary:negative") {
            assert_eq!(got, want);
        }
        if boolean(case, "negativeZero") {
            assert_eq!(got.to_bits(), (-0.0f64).to_bits());
        }
        if case.get("swift_want").num() == want {
            near(got, case.get("swift_want").num(), 1e-6);
        }
    }
    println!(
        "curves: {} cases; maximum error {maximum:e}",
        doc.get("cases").arr().len()
    );
}
fn stats(actual: GovernorStats, want: &Value) {
    near(
        actual.refresh_ms,
        want.get("refreshEstimateMs").num(),
        1e-12,
    );
    assert_eq!(actual.level, want.get("level").num() as u32);
    match opt(want, "emaMs") {
        Some(v) => {
            assert_eq!(actual.has_ema, 1);
            near(actual.ema_ms, v.num(), 1e-12);
        }
        None => assert_eq!(actual.has_ema, 0),
    }
}
#[test]
fn governor_matches_source_cases_and_shared_swift_scenarios() {
    let doc = json::parse(include_str!("../../../conformance/governor/reference.json")).unwrap();
    let swift = json::parse(include_str!(
        "../../../conformance/governor/swift-comparison.json"
    ))
    .unwrap();
    for case in doc.get("cases").arr() {
        let c = case.get("config");
        let defaults = GovernorConfig::default();
        let config = GovernorConfig {
            target_ms: number(c, "targetFrameMs", defaults.target_ms),
            ema_alpha: number(c, "emaAlpha", defaults.ema_alpha),
            pause_gap_ms: number(c, "pauseGapMs", defaults.pause_gap_ms),
            demote_frames: number(c, "demoteFrames", defaults.demote_frames as f64) as u32,
            promote_frames: number(c, "promoteFrames", defaults.promote_frames as f64) as u32,
            settle_frames: number(c, "settleFrames", defaults.settle_frames as f64) as u32,
            initial_level: number(c, "initialLevel", defaults.initial_level as f64) as u32,
            ..defaults
        };
        let mut governor = Governor::new(config).unwrap();
        stats(governor.stats(), case.get("initial"));
        for step in case.get("steps").arr() {
            let samples = step.get("samples").arr();
            for i in 0..step.get("count").num() as usize {
                governor.record(samples[i % samples.len()].num());
            }
            stats(governor.stats(), step.get("want"));
        }
        if let Some(reset) = opt(case, "reset") {
            governor.reset(reset.get("level").num() as u32);
            stats(governor.stats(), reset.get("want"));
        }
        if let Some(name) = case
            .get("source")
            .str()
            .strip_prefix("TS-source-test:swift-shared-")
        {
            let reference = swift
                .get("cases")
                .arr()
                .iter()
                .find(|c| c.get("name").str() == name)
                .unwrap();
            assert_eq!(governor.stats().level, reference.get("level").num() as u32);
        }
    }
    println!(
        "governor: {} TS cases; 3 equivalent Swift scenarios",
        doc.get("cases").arr().len()
    );
}
#[test]
fn governor_refuses_configs_without_a_hysteresis_band() {
    let doc = json::parse(include_str!(
        "../../../conformance/governor/validation.json"
    ))
    .unwrap();
    for case in doc.get("cases").arr() {
        let c = case.get("config");
        let defaults = GovernorConfig::default();
        let config = GovernorConfig {
            target_ms: number(c, "targetFrameMs", defaults.target_ms),
            refresh_floor_ms: number(c, "refreshFloorMs", defaults.refresh_floor_ms),
            demote_factor: number(c, "demoteFactor", defaults.demote_factor),
            promote_refresh_factor: number(
                c,
                "promoteRefreshFactor",
                defaults.promote_refresh_factor,
            ),
            promote_target_factor: number(c, "promoteTargetFactor", defaults.promote_target_factor),
            ..defaults
        };
        assert_eq!(
            Governor::new(config).is_ok(),
            case.get("valid").boolean(),
            "{}",
            case.get("name").str()
        );
    }
}
/// Maps and packs every checkpoint of a packing vector file; returns the checkpoint count and the
/// largest scalar error. Frames without `input.descriptors` go through [`Mapper::map`]; a file
/// with `"level_source": "relative"` maps through [`Mapper::map_ext`] with `input.levels`.
fn check_mapping_and_packing(doc: &Value) -> (usize, f64) {
    let fields: Vec<Field> = doc
        .get("fields")
        .arr()
        .iter()
        .map(|f| Field {
            source: f.get("source").num() as u32,
            source_offset: f.get("source_offset").num() as u32,
            components: f.get("components").num() as u32,
            offset: f.get("offset").num() as u32,
            stride: f.get("stride").num() as u32,
        })
        .collect();
    let packer = Packer::new(&fields, doc.get("block_size").num() as usize).unwrap();
    let mut maximum = 0.0f64;
    let mut comparisons = 0;
    let relative = opt(doc, "level_source").map(Value::str) == Some("relative");
    for case in doc.get("cases").arr() {
        let mut mapper = Mapper::new(MappingConfig::default()).unwrap();
        if relative {
            mapper.set_level_source(LevelSource::Relative);
        }
        for step in case.get("frames").arr() {
            let input = step.get("input");
            let mut frame = DspFrame::ZERO;
            frame.rms = input.get("rms").num();
            frame.loudness_db = input.get("loudness_db").num();
            frame.onset.broadband = input.get("broadband").num();
            frame.onset.low = input.get("low").num();
            frame.band_count = input.get("bands").arr().len() as u32;
            for (dst, src) in frame.spectrum.iter_mut().zip(input.get("bands").arr()) {
                *dst = src.num();
            }
            // FLUX and CENTROID come from descriptors when the checkpoint supplies them.
            let descriptors = opt(input, "descriptors").map(|d| {
                let mut descriptors = Descriptors::ZERO;
                descriptors.centroid_hz = d.get("centroid_hz").num();
                descriptors.spectral_flux = d.get("spectral_flux").num();
                descriptors
            });
            let levels = relative.then(|| {
                let mut levels = Levels::ZERO;
                let shaped = input.get("levels").get("relative_bands").arr();
                levels.band_count = shaped.len() as u32;
                for (dst, src) in levels.relative_bands.iter_mut().zip(shaped) {
                    *dst = src.num();
                }
                levels
            });
            let unavailable = input.get("unavailable").boolean();
            let mut mapped = Mapped::ZERO;
            for _ in 0..step.get("repeat").num() as usize {
                mapped = match (&descriptors, &levels) {
                    (d, Some(l)) => mapper.map_ext(&frame, d.as_ref(), Some(l), unavailable),
                    (Some(d), None) => mapper.map_with(&frame, Some(d), unavailable),
                    (None, None) => mapper.map(&frame, unavailable),
                }
                .unwrap();
            }
            for (got, want) in mapped.values.iter().zip(step.get("values").arr()) {
                near(*got, want.num(), 1e-12);
                maximum = maximum.max((*got - want.num()).abs());
            }
            for (got, want) in mapped.spectrum.iter().zip(step.get("spectrum").arr()) {
                assert_eq!(*got as f64, want.num());
            }
            let host: Vec<f64> = step.get("host").arr().iter().map(Value::num).collect();
            let mut bytes = vec![255; packer.block_size()];
            packer
                .pack(&mapped.values, &mapped.spectrum, &host, &mut bytes)
                .unwrap();
            let expected: Vec<u8> = step
                .get("bytes")
                .arr()
                .iter()
                .map(|v| v.num() as u8)
                .collect();
            assert_eq!(bytes, expected);
            comparisons += 1;
        }
    }
    (comparisons, maximum)
}
#[test]
fn mapping_and_packing_match_reference_including_unavailable_state() {
    let doc = json::parse(include_str!("../../../conformance/packing/reference.json")).unwrap();
    let (comparisons, maximum) = check_mapping_and_packing(&doc);
    assert_eq!(comparisons, 19);
    println!("mapping/packing: {comparisons} checkpoints; scalar maximum error {maximum:e}; f32 spectrum and bytes exact");
}
#[test]
fn mapping_with_descriptors_matches_the_standard_library_model() {
    let doc = json::parse(include_str!(
        "../../../conformance/packing/descriptors.json"
    ))
    .unwrap();
    let (comparisons, maximum) = check_mapping_and_packing(&doc);
    assert_eq!(comparisons, 10);
    println!("mapping/packing with descriptors: {comparisons} checkpoints; scalar maximum error {maximum:e}; f32 spectrum and bytes exact");
}
#[test]
fn mapping_with_relative_levels_matches_the_standard_library_model() {
    let doc = json::parse(include_str!("../../../conformance/packing/levels.json")).unwrap();
    let (comparisons, maximum) = check_mapping_and_packing(&doc);
    assert_eq!(comparisons, 7);
    println!("mapping/packing with relative levels: {comparisons} checkpoints; scalar maximum error {maximum:e}; f32 spectrum and bytes exact");
}
#[test]
fn visual_uniforms_fields_match_schema_vector() {
    let doc = json::parse(include_str!(
        "../../../conformance/packing/visual-uniforms.json"
    ))
    .unwrap();
    assert_eq!(
        doc.get("block_size").num() as usize,
        visual_uniforms::BLOCK_SIZE
    );
    assert_eq!(
        doc.get("host_values").num() as usize,
        visual_uniforms::HOST_VALUES
    );
    let fields = doc.get("fields").arr();
    assert_eq!(fields.len(), visual_uniforms::FIELDS.len());
    for (want, got) in fields.iter().zip(&visual_uniforms::FIELDS) {
        let want = Field {
            source: want.get("source").num() as u32,
            source_offset: want.get("source_offset").num() as u32,
            components: want.get("components").num() as u32,
            offset: want.get("offset").num() as u32,
            stride: want.get("stride").num() as u32,
        };
        assert_eq!(*got, want);
    }
    let packer = Packer::new(&visual_uniforms::FIELDS, visual_uniforms::BLOCK_SIZE).unwrap();
    let case = doc.get("case");
    let mut scalars = [0.0; 9];
    for (dst, src) in scalars.iter_mut().zip(case.get("scalars").arr()) {
        *dst = src.num();
    }
    let mut spectrum = [0.0; 64];
    for (dst, src) in spectrum.iter_mut().zip(case.get("spectrum").arr()) {
        *dst = src.num() as f32;
    }
    let host: Vec<f64> = case.get("host").arr().iter().map(Value::num).collect();
    let mut bytes = vec![255; visual_uniforms::BLOCK_SIZE];
    packer.pack(&scalars, &spectrum, &host, &mut bytes).unwrap();
    let expected: Vec<u8> = case
        .get("bytes")
        .arr()
        .iter()
        .map(|v| v.num() as u8)
        .collect();
    assert_eq!(bytes, expected);
}
